import { test, expect } from '@playwright/test';

test.describe('Pagination Controls', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/results');
  });

  test('should load the correct page of results when clicking pagination buttons', async ({ page }) => {
    // Verify initial page loads
    const resultsList = page.getByRole('region', { name: /results/i });
    await expect(resultsList).toBeVisible();
    const pageIndicator = page.getByText('Page 1 of 5');
    await expect(pageIndicator).toBeVisible();

    // Verify first page results are displayed
    const resultItems = page.getByRole('listitem');
    const count = await resultItems.count();
    expect(count).toBeGreaterThan(0);

    // Click next page button
    const nextPageButton = page.getByRole('button', { name: /next/i });
    await expect(nextPageButton).toBeVisible();
    await nextPageButton.click();

    // Verify page indicator updates
    await expect(pageIndicator).toHaveText('Page 2 of 5');

    // Verify results are updated
    const updatedResultItems = page.getByRole('listitem');
    const updatedCount = await updatedResultItems.count();
    expect(updatedCount).toBeGreaterThan(0);

    // Verify page number is updated
    const pageNumber = page.getByText('2');
    await expect(pageNumber).toBeVisible();

    // Click last page button
    const lastPageButton = page.getByRole('button', { name: /last/i });
    await expect(lastPageButton).toBeVisible();
    await lastPageButton.click();

    // Verify page indicator shows last page
    await expect(pageIndicator).toHaveText('Page 5 of 5');

    // Verify page number is 5
    const pageNumberFinal = page.getByText('5');
    await expect(pageNumberFinal).toBeVisible();
  });

  test('should handle pagination when page is out of bounds', async ({ page }) => {
    // Navigate to a page that doesn't exist
    const pageInput = page.getByLabel(/page number/i);
    await pageInput.fill('99');

    // Click go button
    const goButton = page.getByRole('button', { name: /go/i });
    await goButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/page not found/i);
    await expect(errorMessage).toBeVisible();

    // Verify results list is empty
    const resultsList = page.getByRole('region', { name: /results/i });
    const resultItems = page.getByRole('listitem');
    const count = await resultItems.count();
    expect(count).toBe(0);

    // Verify pagination controls are disabled or hidden
    const nextPageButton = page.getByRole('button', { name: /next/i });
    const nextPageDisabled = await nextPageButton.isDisabled();
    expect(pageNumber).toBe(true);

    // Verify previous page button is enabled
    const prevPageButton = page.getByRole('button', { name: /previous/i });
    const prevPageEnabled = await prevPageButton.isEnabled();
    expect(prevPageEnabled).toBe(true);

    // Navigate back to page 1
    await pageInput.fill('1');
    await goButton.click();

    // Verify page indicator resets
    const pageIndicator = page.getByText('Page 1 of 5');
    await expect(pageIndicator).toBeVisible();
  });
});
